<script setup>
import {reactive,ref} from 'vue';import {ElMessage} from 'element-plus';import {login} from '../../api/auth.js'
const form=reactive({phone:'13800138000',password:'123456',remember:true});const loading=ref(false);const rules={phone:[{required:true,message:'请输入手机号',trigger:'blur'},{pattern:/^1\d{10}$/,message:'请输入正确手机号',trigger:'blur'}],password:[{required:true,message:'请输入密码',trigger:'blur'}]};const formRef=ref()
async function submit(){await formRef.value.validate();loading.value=true;try{await login(form);ElMessage.success('登录成功');location.href='/workspace'}finally{loading.value=false}}
</script>
<template><div class="auth-shell"><div class="auth-visual"></div><div class="auth-panel"><div class="auth-box"><span class="eyebrow">欢迎回来</span><h1>登录木序定制</h1><p class="muted">查看您的设计方案与订单进度</p><el-form ref="formRef" :model="form" :rules="rules" label-position="top" @submit.prevent="submit"><el-form-item label="手机号" prop="phone"><el-input v-model="form.phone"/></el-form-item><el-form-item label="密码" prop="password"><el-input v-model="form.password" type="password" show-password/></el-form-item><div class="auth-options"><el-checkbox v-model="form.remember">记住登录状态</el-checkbox><a class="text-link">忘记密码</a></div><el-button type="primary" :loading="loading" native-type="submit" style="width:100%">登录</el-button><p class="auth-switch">还没有账号？<router-link to="/register">立即注册</router-link></p></el-form></div></div></div></template>
<style scoped>.auth-options{display:flex;justify-content:space-between;margin:-2px 0 22px}.auth-switch{text-align:center;color:var(--c-muted);margin-top:20px}.auth-switch a{color:var(--c-primary)}</style>
